// Generate src/prompts.generated.ts from the crc-docs question skills.
//
//   npm run sync:prompts -- --from ../crc-docs
//
// crc-docs is the source of truth for the workflows. Each skill becomes an MCP
// prompt whose message carries the full SKILL.md, so the prompt and the skill
// never diverge. The generated file records the source commit and a checksum
// per skill. The checkout must be clean so the commit describes the content.

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const fromIndex = process.argv.indexOf("--from");
const source = resolve(
  fromIndex > 0 ? process.argv[fromIndex + 1] : join(root, "../crc-docs"),
);
const skillsDir = join(source, ".agents/skills");
const REPOSITORY = "https://github.com/RiskThinking/crc-docs";

// One argument per prompt: what the person is asking about. The skill text
// explains what to do with it.
const ARGUMENTS = {
  "how-exposed-is-this-company": {
    name: "company",
    description: "Company name or stock ticker, e.g. Walmart or WMT",
  },
  "how-hard-will-it-rain": {
    name: "place",
    description: "City, address, or latitude and longitude",
  },
  "how-hot-will-it-get": {
    name: "place",
    description: "City, address, or latitude and longitude",
  },
  "which-sites-are-most-at-risk": {
    name: "sites",
    description:
      "The sites to compare: names with addresses or latitude and longitude",
  },
  "will-my-farm-get-drier": {
    name: "place",
    description: "Farm, field, or growing region",
  },
};

const git = (...args) =>
  execFileSync("git", ["-C", source, ...args], { encoding: "utf8" }).trim();
if (git("status", "--porcelain", "--", ".agents/skills")) {
  throw new Error(`${skillsDir} has uncommitted changes; commit them first`);
}
const commit = git("rev-parse", "HEAD");

const prompts = [];
for (const name of (await readdir(skillsDir)).sort()) {
  const argument = ARGUMENTS[name];
  if (!argument) {
    throw new Error(`No prompt argument defined for skill ${name}`);
  }
  const text = await readFile(join(skillsDir, name, "SKILL.md"), "utf8");
  const frontmatter = text.match(/^---\n([\s\S]*?)\n---\n/);
  const description = frontmatter?.[1].match(/^description: (.+)$/m)?.[1];
  const title = text.match(/^# (.+)$/m)?.[1];
  if (frontmatter?.[1].match(/^name: (.+)$/m)?.[1] !== name) {
    throw new Error(`${name}/SKILL.md frontmatter name does not match`);
  }
  if (!description || !title) {
    throw new Error(`${name}/SKILL.md needs a description and a # title`);
  }
  prompts.push({
    name,
    title,
    description,
    argument,
    skill: text.slice(frontmatter[0].length).trim(),
    source: `${REPOSITORY}/blob/${commit}/.agents/skills/${name}/SKILL.md`,
    sha256: createHash("sha256").update(text).digest("hex"),
  });
}
for (const name of Object.keys(ARGUMENTS)) {
  if (!prompts.some((prompt) => prompt.name === name)) {
    throw new Error(`Skill ${name} no longer exists in crc-docs`);
  }
}

const output = `// Generated by scripts/sync-prompts.mjs from ${REPOSITORY}
// at commit ${commit}. Do not edit; run \`npm run sync:prompts\`.

export type SkillPrompt = {
  name: string;
  title: string;
  description: string;
  argument: { name: string; description: string };
  skill: string;
  source: string;
  sha256: string;
};

export const SKILL_PROMPTS_COMMIT = ${JSON.stringify(commit)};

export const SKILL_PROMPTS: readonly SkillPrompt[] = ${JSON.stringify(prompts, null, 2)};
`;
await writeFile(join(root, "src/prompts.generated.ts"), output);
console.log(`Synchronized ${prompts.length} prompts from crc-docs ${commit}`);
